def current_rows(spark: SparkSession, table: str, last_processed_version: int) -> DataFrame:
    """Inserted and updated rows since the last run, with their new values."""
    changes = spark.read.option("readChangeFeed", "true").option("startingVersion", last_processed_version + 1).table(table)
    return changes.filter(F.col("_change_type").isin(["insert", "update_postimage"]))
